parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "customer_name": {
      "type": "string",
      "description": "The customer's full name, exactly as provided in the message. Return an empty string if no name is provided."
    },
    "customer_email": {
      "type": "string",
      "description": "The customer's email address, exactly as provided in the message. Return an empty string if no email is provided."
    }
  },
  "required": [
    "customer_name",
    "customer_email"
  ],
  "additionalProperties": false
}

parameters.message:
={{
  !$('Extract Customer Identity').item.json.output.customer_name &&
  !$('Extract Customer Identity').item.json.output.customer_email
    ? "Please provide your name and email address."
    : !$('Extract Customer Identity').item.json.output.customer_name
      ? "Please provide your name."
      : "Please provide your email address."
}}

